// TEST-ONLY Worker for tests/worker/quotation-e2e.ts; never deployed or referenced by any wrangler
// config in the repository. One local port, two origins:
// - http://127.0.0.1:<port> is the public site: the real public Worker (worker/public/index.ts)
//   with the test build's static assets; /api/quote/* goes to the real handleQuote with a
//   test-only pause point between its authorization read and its write;
// - http://localhost:<port> is the owner Worker: the real owner handler with Access keys
//   generated by the test run (TEST_ACCESS_JWKS) and loopback HTTP origins allowed
//   (localLoopbackOrigin), exactly as tests/worker/owner-test-worker.ts.
// The scheduled email run uses an in-memory mock provider; nothing is sent anywhere.
// Test-only routes on 127.0.0.1 (/__test/...), all inside this Worker so no other process touches
// the running local database:
//   invitations           the quotation links the mock provider "received" (in memory)
//   pause|release?action  hold accept/decline/simulate requests between their check and write,
//                         or (action=read-<action>) just before the response snapshot is read
//   paused?action         how many requests are being held
//   clock?offset          shift the customer API's clock (to advance the hourly quota window)
//   supersede?ref         issue a newer link generation, with history recorded under it
//                         (history=0: without); unsupersede?ref restores generation 1
//   unrevoke?ref          undo revoke (to show a retry working once the link is valid again)
//   bump-version?ref      change the quotation's version (as a future owner action would)
//   revoke?ref            revoke a quotation's links (as the future owner action would)
//   fixture?ms            insert a short-lived approved quotation (immutable once inserted)
//   state?ref             a quotation's status and its customer events and simulated rows
// It refuses every other host, so even if it were run elsewhere it would serve nothing.

import publicWorker, { type PublicEnv } from '../../worker/public/index.ts';
import { handleQuote } from '../../worker/public/quote.ts';
import { handleOwner, type OwnerEnv } from '../../worker/owner/handler.ts';
import { runScheduled, runScheduledRetention, type SenderEnv } from '../../worker/owner/scheduled.ts';
import { sha256Hex } from '../../src/lib/quotation/owner-form.ts';
import { currentLinkKey, quoteLinkToken } from '../../src/lib/quotation/quote-link.ts';
import { createMockProvider } from '../support/mock-email.ts';
import { localLoopbackOrigin } from './owner-test-worker.ts';

const provider = createMockProvider();
type Env = PublicEnv & OwnerEnv & SenderEnv & { TEST_ACCESS_JWKS?: string };
type Mutation = string; // accept | decline | simulate, or read-<action>
const hold: Record<Mutation, boolean> = {};
const held: Record<Mutation, number> = {};
let fixtureSeq = 0;
let clockOffset = 0;

/** Waits while the action is held (polling: no promise is shared across requests). */
async function pausePoint(action: Mutation): Promise<void> {
  held[action] ??= 0;
  if (!hold[action]) return;
  held[action]++;
  const until = Date.now() + 20000;
  while (hold[action] && Date.now() < until) await new Promise((done) => setTimeout(done, 25));
  held[action]--;
}

async function testRoute(url: URL, env: Env): Promise<Response> {
  const db = env.DB!;
  const action = url.searchParams.get('action') as Mutation;
  switch (url.pathname) {
    case '/__test/invitations':
      return Response.json(
        provider.inbox.map((entry) => ({ key: entry.key, to: entry.message.to, subject: entry.message.subject, link: /^(http\S+\/quote\/#t=\S+)$/m.exec(entry.message.text)?.[1] ?? null })),
      );
    case '/__test/pause':
      hold[action] = true;
      return Response.json({ ok: true });
    case '/__test/release':
      hold[action] = false;
      return Response.json({ ok: true });
    case '/__test/paused':
      return Response.json({ held: held[action] ?? 0 });
    case '/__test/clock':
      clockOffset = Number(url.searchParams.get('offset'));
      return Response.json({ offset: clockOffset });
    case '/__test/supersede': {
      const ref = url.searchParams.get('ref');
      const quote = await db.prepare('SELECT id FROM quotes WHERE ref = ?1').bind(ref).first<{ id: string }>();
      const newer = await sha256Hex(`v1.${crypto.randomUUID().replace(/-/g, '').padEnd(43, 'N').slice(0, 43)}`);
      await db.batch([
        db.prepare('INSERT INTO quote_links (token_hash, quote_id, link_generation, link_key_version, created_at) VALUES (?1, ?2, 2, 1, ?3)').bind(newer, quote!.id, Date.now()),
        db.prepare('UPDATE quotes SET link_generation = 2, token_hash = ?1 WHERE id = ?2').bind(newer, quote!.id),
        ...(url.searchParams.get('history') === '0'
          ? []
          : [
              db
                .prepare("INSERT INTO simulated_checkouts (id, quote_id, attempt_id, method, outcome, created_at) VALUES (?1, ?2, ?3, 'bank', 'success', ?4)")
                .bind(crypto.randomUUID(), quote!.id, crypto.randomUUID(), Date.now()),
            ]),
      ]);
      return Response.json({ superseded: true });
    }
    case '/__test/unsupersede': {
      const quote = await db.prepare('SELECT id FROM quotes WHERE ref = ?1').bind(url.searchParams.get('ref')).first<{ id: string }>();
      const first = await db.prepare('SELECT token_hash FROM quote_links WHERE quote_id = ?1 AND link_generation = 1').bind(quote!.id).first<{ token_hash: string }>();
      await db.batch([
        db.prepare('DELETE FROM quote_links WHERE quote_id = ?1 AND link_generation > 1').bind(quote!.id),
        db.prepare('UPDATE quotes SET link_generation = 1, token_hash = ?1 WHERE id = ?2').bind(first!.token_hash, quote!.id),
      ]);
      return Response.json({ restored: true });
    }
    case '/__test/unrevoke': {
      const result = await db
        .prepare('UPDATE quote_links SET revoked_at = NULL WHERE quote_id = (SELECT id FROM quotes WHERE ref = ?1)')
        .bind(url.searchParams.get('ref'))
        .run();
      return Response.json({ restored: result.meta.changes });
    }
    case '/__test/bump-version': {
      const result = await db.prepare('UPDATE quotes SET version = version + 1 WHERE ref = ?1').bind(url.searchParams.get('ref')).run();
      return Response.json({ changed: result.meta.changes });
    }
    case '/__test/revoke': {
      const result = await db
        .prepare('UPDATE quote_links SET revoked_at = ?2 WHERE quote_id = (SELECT id FROM quotes WHERE ref = ?1)')
        .bind(url.searchParams.get('ref'), Date.now())
        .run();
      return Response.json({ revoked: result.meta.changes });
    }
    case '/__test/fixture': {
      // A short-lived approved quotation, created directly (approval allows at least one day).
      const now = Date.now();
      const seq = ++fixtureSeq;
      const requestId = crypto.randomUUID();
      const quoteId = crypto.randomUUID();
      const link = (await currentLinkKey(env as unknown as Record<string, unknown>))!;
      const token = await quoteLinkToken(link, quoteId, 1);
      const hash = await sha256Hex(token);
      const expiresAt = now + Number(url.searchParams.get('ms'));
      const status = url.searchParams.get('status') === 'accepted' ? 'accepted' : 'approved';
      await db.batch([
        db
          .prepare(
            `INSERT INTO quote_requests (id, ref, ref_year, ref_seq, submission_id, payload_hash, client_hash, hash_key_version, source, status, service, plan,
               name, email, organization, phone, organization_type, project_need, message, privacy_ack_version, created_at, updated_at)
             VALUES (?1, ?2, 1999, ?3, ?4, 'h', 'c', '1', 'js', 'quoted', '', 'starter', 'TEST Fixture', 'fixture@example.test', 'TEST ONLY', '', 'other', 'TEST ONLY fixture', '', 'v', ?5, ?5)`,
          )
          .bind(requestId, `BT-R-1999-${9000 + seq}`, 9000 + seq, crypto.randomUUID(), now),
        db
          .prepare(
            `INSERT INTO quotes (id, request_id, ref, ref_year, ref_seq, status, version, scope_text, amount_centavos, currency, validity_days,
               link_key_version, link_generation, token_hash, expires_at, snap_name, snap_email, snap_scope, snap_amount_centavos, snap_validity_days,
               approved_at, approved_by, accepted_at, created_at, updated_at)
             VALUES (?1, ?2, ?3, 1999, ?4, ?5, 2, 'TEST ONLY: short-lived fixture.', 100000, 'PHP', 1, 1, 1, ?6, ?7, 'TEST Fixture', 'fixture@example.test',
               'TEST ONLY: short-lived fixture.', 100000, 1, ?8, 'owner@example.test', ?9, ?8, ?8)`,
          )
          .bind(quoteId, requestId, `BT-Q-1999-${9000 + seq}`, 9000 + seq, status, hash, expiresAt, now, status === 'accepted' ? now : null),
        db.prepare('INSERT INTO quote_links (token_hash, quote_id, link_generation, link_key_version, created_at) VALUES (?1, ?2, 1, 1, ?3)').bind(hash, quoteId, now),
      ]);
      return Response.json({ token, ref: `BT-Q-1999-${9000 + seq}`, expiresAt, link: `${env.PUBLIC_ORIGIN}/quote/#t=${token}` });
    }
    case '/__test/state': {
      const row = await db
        .prepare(
          `SELECT q.status, q.accepted_at, q.declined_at,
             (SELECT COUNT(*) FROM quote_events e WHERE e.quote_id = q.id AND e.actor = 'customer') AS events,
             (SELECT COUNT(*) FROM simulated_checkouts s WHERE s.quote_id = q.id) AS simulations
           FROM quotes AS q WHERE q.ref = ?1`,
        )
        .bind(url.searchParams.get('ref'))
        .first();
      return Response.json(row);
    }
  }
  return new Response('Not found', { status: 404 });
}

const QUOTE_API = /^\/api\/quote\/(view|accept|decline|simulate)$/;

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    if (!env.TEST_ACCESS_JWKS) return new Response('Not found', { status: 404 });
    if (url.hostname === 'localhost') {
      const keys = (JSON.parse(env.TEST_ACCESS_JWKS) as { keys: (JsonWebKey & { kid: string })[] }).keys;
      return handleOwner(request, env, async (kid) => keys.find((key) => key.kid === kid) ?? null, Date.now(), localLoopbackOrigin);
    }
    if (url.hostname !== '127.0.0.1') return new Response('Not found', { status: 404 });
    if (url.pathname.startsWith('/__test/')) return testRoute(url, env);
    const quote = QUOTE_API.exec(url.pathname);
    if (quote) {
      return handleQuote(request, env, quote[1] as 'view', () => Date.now() + clockOffset, {
        beforeWrite: pausePoint,
        beforeRead: (action) => pausePoint(`read-${action}`),
      });
    }
    return publicWorker.fetch(request, env);
  },

  async scheduled(_controller: unknown, env: Env): Promise<void> {
    await runScheduledRetention(env, () => Date.now(), localLoopbackOrigin);
    await runScheduled(env, () => provider.transport, () => Date.now(), localLoopbackOrigin, { quotationEmailsReady: true });
  },
};
